const message = $input.first().json.message;

return [
  {
    json: {
      text: message.text
    }
  }
];

try {
  const inputData = $input.first().json;

  let aiResponse =
    inputData.output ||
    inputData.content ||
    inputData.response ||
    inputData;

  // Si la IA devuelve texto, intenta extraer el JSON
  if (typeof aiResponse === 'string') {
    const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);

    if (jsonMatch) {
      aiResponse = JSON.parse(jsonMatch[0]);
    } else {
      aiResponse = JSON.parse(aiResponse);
    }
  }

  // Campos mínimos obligatorios
  const requiredFields = [
    'amount',
    'transaction_type'
  ];

  const missingFields = requiredFields.filter((field) => {
    return (
      aiResponse[field] === undefined ||
      aiResponse[field] === null ||
      aiResponse[field] === ''
    );
  });

  if (missingFields.length > 0) {
    throw new Error(
      `Missing required fields: ${missingFields.join(', ')}`
    );
  }

  // Validar monto
  const amount = Number(aiResponse.amount);

  if (!Number.isFinite(amount) || amount <= 0) {
    throw new Error('Invalid amount detected');
  }

  const telegramMessage =
    $('Telegram Bot Trigger').item.json.message;

  // ---------------------------------------------
// VALIDACIÓN DEL MENSAJE ORIGINAL DE TELEGRAM
// ---------------------------------------------

const originalText = String(
  telegramMessage.text || ''
).trim();

  // Fecha real del mensaje de Telegram
  const getTelegramDate = () => {
    const d = new Date(telegramMessage.date * 1000);

    const parts = new Intl.DateTimeFormat('en-CA', {
      timeZone: 'America/Mexico_City',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    }).formatToParts(d);

    const get = (type) =>
      parts.find((p) => p.type === type)?.value;

    return `${get('year')}-${get('month')}-${get('day')}`;
  };

  let date = aiResponse.date;

  // Si la IA no detectó fecha, usa la fecha real del mensaje
  if (
    typeof date !== 'string' ||
    !/^\d{4}-\d{2}-\d{2}$/.test(date)
  ) {
    date = getTelegramDate();
  }

  const generateId = () => {
    return (
      'txn_' +
      telegramMessage.message_id +
      '_' +
      telegramMessage.from.id
    );
  };

  const transaction = {
    id: generateId(),

    vendor:
      aiResponse.vendor === null ||
      aiResponse.vendor === undefined ||
      String(aiResponse.vendor).trim() === ''
        ? 'Sin especificar'
        : String(aiResponse.vendor).trim(),

    amount,

    currency:
      String(aiResponse.currency || 'MXN').toUpperCase(),

    date,

    transaction_type:
      String(aiResponse.transaction_type || 'purchase')
        .toLowerCase() === 'compra'
        ? 'purchase'
        : String(aiResponse.transaction_type || 'purchase')
            .toLowerCase(),

    category:
      String(aiResponse.category || 'Otros').trim(),

    subcategory:
      String(aiResponse.subcategory ?? '').trim() ||
      'Sin especificar',

    description:
      String(
        aiResponse.description ||
        telegramMessage.text ||
        'Gasto registrado por Telegram'
      ).trim(),

    processed_date:
      new Date().toISOString(),

    user_id:
      telegramMessage.from.id,

    username:
      telegramMessage.from.username || 'unknown',

    error: false
  };

  return {
    json: transaction
  };

} catch (error) {
  const telegramMessage =
    $('Telegram Bot Trigger').item.json.message;

  return {
    json: {
      error: true,
      message: error.message,
      user_id: telegramMessage.from.id
    }
  };
}

