const text = String($json.text || '').trim();

const amounts = text.match(
  /\$?\s*\d{1,3}(?:,\d{3})*(?:\.\d{1,2})?|\$?\s*\d+(?:\.\d{1,2})?/g
);

if (!amounts || amounts.length === 0) {
  return [{
    json: {
      error: true,
      valid_expense: false,
      message:
        'No encontré ningún monto en tu mensaje. Ejemplo: "Gasté $120 en tacos".'
    }
  }];
}

const expenseIntent =
  /(gast[eé]|pagu[eé]|compr[eé]|cost[oó]|fueron|salieron|pago|gasto|compra)/i;

if (!expenseIntent.test(text)) {
  return [{
    json: {
      error: true,
      valid_expense: false,
      message:
        'No pude identificar el mensaje como un gasto. Ejemplo: "Gasté $120 en tacos".'
    }
  }];
}

const parsedAmounts = amounts
  .map(v =>
    Number(
      v.replace('$', '')
       .replace(/\s+/g, '')
       .replace(/,/g, '')
    )
  )
  .filter(v => Number.isFinite(v) && v > 0);

const uniqueAmounts = [...new Set(parsedAmounts)];

if (uniqueAmounts.length > 1) {
  return [{
    json: {
      error: true,
      valid_expense: false,
      message:
        'Encontré varios montos. Envía un solo gasto por mensaje.'
    }
  }];
}

return [{
  json: {
    text,
    user_amount: uniqueAmounts[0],
    error: false,
    valid_expense: true
  }
}];

const response = $input.first().json;

// Notion devuelve las páginas dentro de results
const expenses = response.results || [];

let total = 0;

const details = [];

for (const page of expenses) {
  const props = page.properties || {};

  const amount = Number(props.Monto?.number || 0);

  const description =
    props['Descripción']?.title?.[0]?.plain_text ||
    'Sin descripción';

  if (Number.isFinite(amount)) {
    total += amount;

    details.push({
      amount,
      description
    });
  }
}

const today = new Intl.DateTimeFormat('es-MX', {
  timeZone: 'America/Mexico_City',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
}).format(new Date());

return [
  {
    json: {
      total,
      count: details.length,
      expenses: details,
      today
    }
  }
];
